// Build the technique-name caption for a Special Move cutscene.
// wh receives the caption size so it can be centred later.
local fn = "whs0035";
local wh = [0, 0];
CMND_2DO_CREATE_TELOP("skill_name", 0, 12, 0, fn, wh, 6);

CMND_2DO_STATE_DRAW_TELOP("skill_name", true);
CMND_2DO_POS_SET_TELOP("skill_name", 200 - wh[0] / 2, 204 - wh[1] / 2);

// Tactic scripts are named "whtNNNN"; the caption needs the tactic ID
// "iftNNNN", which MakeTacFileName builds.
local skl_0 = "wht0004";
if (IsTacName(skl_0))
{
	skl_0 = MakeTacFileName(skl_0);
}
local vTelopSize_0 = [0, 0];
CMND_2DO_CREATE_TELOP("tactic_0", 1, 12, 0, skl_0, vTelopSize_0, 6);

// Leave out the spacing argument to use the engine default (4.0).
local size = [0, 0];
if (CMND_2DO_CREATE_TELOP("move_name", 0, 12, 0, "whs0035", size) == null)
{
	// Unknown ID: no caption was created.
}
